mapper.insert:
/* common.insertBmsEcmPod : 전자상거래 POD 저장 */
INSERT INTO TB_ECM_POD_05 (
        ENT_CODE
        , OD_JOB_NO
        , POD_STATUS
        , POD_NAME
        , POD_DATE
        , POD_TIME
        , REMARKS
        , REGISTER_USER_ID
        , REGISTER_DATE_TIME
        , UPDATE_USER_ID
        , UPDATE_DATE_TIME
) VALUES (
       #{entCode}
       , #{odJobNo}
       , 'ECM288'
       , #{podName}


                ,CONVERT(DATE, #{podDate} , 120)
                , #{podTime}


                , GETDATE()
                , SUBSTRING(CONVERT(VARCHAR(10), GETDATE(), 108), 1, 8)


       , #{remarks}
       , #{registerUserId}
       , GETDATE()
       , #{registerUserId}
       , GETDATE()
       );
